const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
const secondary = (overlap, floor, yieldRate, reduction = 1) => Math.max(floor, 1 - clamp01(overlap) * yieldRate) * reduction;
export function projectileContourOwnershipPresentation(input, reducedFlash = false) { const protectedContour = input.critical || input.bossActive; return { canonicalContourScale: 1, secondaryContourScale: secondary(input.overlap, protectedContour ? .95 : .91, protectedContour ? .05 : .09, reducedFlash ? .99 : 1), presentationOnly: true }; }
export function impactContourOwnershipPresentation(input, reducedFlash = false) { const protectedContour = input.critical; return { canonicalContourScale: 1, secondaryContourScale: secondary(input.overlap, protectedContour ? .93 : .86, protectedContour ? .07 : .14, reducedFlash ? .99 : 1), presentationOnly: true }; }
export function hazardContourOwnershipPresentation(input, reducedFlash = false) { const protectedContour = input.telegraph || input.critical; return { canonicalContourScale: 1, secondaryContourScale: secondary(input.overlap, protectedContour ? .94 : .85, protectedContour ? .06 : .15, reducedFlash ? .99 : 1), presentationOnly: true }; }
export function safeLaneContourOwnershipPresentation(input, reducedFlash = false) { const confidence = clamp01(input.confidence), floor = input.visible ? .965 + .02 * confidence : .9; return { canonicalContourScale: 1, secondaryContourScale: secondary(input.overlap, floor, input.visible ? .035 : .1, reducedFlash ? .995 : 1), presentationOnly: true }; }
export function specialistContourOwnershipPresentation(input, reducedMotion = false) { const action = input.owner === 'special' || input.owner === 'attack', protectedContour = input.critical || action, floor = protectedContour ? .93 : input.owner === 'recovery' ? .84 : .88, yieldRate = protectedContour ? .07 : input.owner === 'recovery' ? .16 : .12; return { canonicalContourScale: 1, secondaryContourScale: secondary(input.overlap, floor, yieldRate, reducedMotion ? .99 : 1), presentationOnly: true }; }
export function contourOwnershipBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), stress = clamp01(clamp01(input.crowd) * .76 + critical * .2 + (input.bossActive ? .04 : 0)), laneReserve = input.safeLaneVisible ? .012 : 0, accessibility = (reducedMotion ? .995 : 1) * (reducedFlash ? .995 : 1); return { stress, canonicalContourScale: 1, secondaryContourScale: Math.max(.925, 1 - stress * .06 - laneReserve) * accessibility, safeLaneContourScale: 1, presentationOnly: true }; }
